// Token bucket rate limiter with lazy refill stored in Redis
// Uses a Lua script so the read-modify-write is atomic
import { Redis } from 'ioredis';

const redis = new Redis(process.env.REDIS_URL);

// Lua: read state, compute refill, consume token, write back — all atomic
const tokenBucketScript = `
  local key = KEYS[1]
  local capacity = tonumber(ARGV[1])
  local refillRate = tonumber(ARGV[2])  -- tokens per second
  local now = tonumber(ARGV[3])         -- unix ms
  local ttl = tonumber(ARGV[4])         -- key expiry (seconds)

  -- Load current state (tokens, lastRefill)
  local data = redis.call('HMGET', key, 'tokens', 'last_refill')
  local tokens = tonumber(data[1]) or capacity
  local lastRefill = tonumber(data[2]) or now

  -- Compute tokens to add based on elapsed time
  local elapsedSec = (now - lastRefill) / 1000
  local newTokens = math.min(capacity, tokens + elapsedSec * refillRate)

  -- Try to consume one token
  if newTokens < 1 then
    return 0  -- rejected
  end

  newTokens = newTokens - 1
  redis.call('HMSET', key, 'tokens', newTokens, 'last_refill', now)
  redis.call('EXPIRE', key, ttl)
  return 1  -- allowed
`;

async function tokenBucketAllow(identifier, capacity, refillRate) {
  const key = `tb:${identifier}`;
  const now = Date.now();
  const ttl = Math.ceil(capacity / refillRate) + 10; // auto-cleanup
  const result = await redis.eval(
    tokenBucketScript, 1, key,
    capacity, refillRate, now, ttl
  );
  return result === 1;
}

// Express middleware factory
function tokenBucketMiddleware(capacity = 60, refillRate = 10) {
  return async (req, res, next) => {
    const identifier = req.user?.id || req.headers['x-api-key'] || req.ip;
    const allowed = await tokenBucketAllow(identifier, capacity, refillRate);
    if (!allowed) {
      const retryAfter = Math.ceil(1 / refillRate); // seconds until next token
      res.set('Retry-After', retryAfter);
      res.set('X-RateLimit-Limit', capacity);
      return res.status(429).json({
        error: 'Too Many Requests',
        message: `Rate limit exceeded. Retry after ${retryAfter}s.`,
        retryAfter,
      });
    }
    res.set('X-RateLimit-Limit', capacity);
    next();
  };
}

// Apply different limits to different routes
app.use('/api/public', tokenBucketMiddleware(60, 1));   // 60 burst, 1/sec sustained
app.use('/api/v1', tokenBucketMiddleware(300, 10));      // 300 burst, 10/sec sustained
app.use('/auth/login', tokenBucketMiddleware(5, 0.017)); // 5 burst, ~1/min

sections.content:
Real systems do not apply a single rate limit — they stack multiple policies simultaneously, each targeting a different dimension of abuse or fairness:

**IP-based limits** catch unauthenticated abuse (login brute force, scraping, DDoS amplification). Example: `5 login attempts per IP per 5 minutes`. Weakness: shared NAT IPs (corporate networks, mobile carriers) cause false positives for legitimate users. Reserve IP limits for truly unauthenticated endpoints or pair them with user-ID limits for authenticated ones.

**User ID / API Key limits** enforce per-customer quotas and fair use. Example: `1000 req/min per API key`. This is the right dimension for authenticated APIs — it cannot be evaded by changing IP, and it does not penalize innocent users sharing an IP.

**Endpoint-specific limits** apply tighter constraints to expensive or sensitive operations. A `GET /health` endpoint can handle 10,000 req/sec; a `POST /invoice/generate` that triggers database writes and emails should not. Example overrides: `POST /auth/login: 5/5min per IP`, `POST /export/csv: 3/hour per user`, `GET /search: 60/min per key`.

**Global limits** cap total traffic regardless of source — a safety valve for your infrastructure. Example: `20,000 req/sec total; return 503 above this`. This protects against scenarios where millions of legitimate clients all retry simultaneously (thundering herd after an outage).

**Applying multiple policies:** Check all applicable policies and apply the most restrictive one. In code, this means running checks in order and short-circuiting as soon as one rejects:

```js
const policies = [
  { key: `ip:${req.ip}`, limit: 60, window: 60 },
  { key: `user:${req.user.id}`, limit: 1000, window: 60 },
  { key: `endpoint:${req.method}:${req.path}:${req.user.id}`, limit: 10, window: 60 }
];
for (const policy of policies) {
  if (await isLimited(policy)) return res.status(429).json(...);
}
```

This pattern also makes policy management transparent and auditable — each rule is an explicit, readable entry.

