// Sliding window counter — O(1) memory, fair approximation
// Used by NGINX limit_req and Redis cell
import { Redis } from 'ioredis';
const redis = new Redis(process.env.REDIS_URL);

const slidingWindowScript = `
  local currKey = KEYS[1]   -- current window key
  local prevKey = KEYS[2]   -- previous window key
  local limit = tonumber(ARGV[1])
  local windowSec = tonumber(ARGV[2])
  local now = tonumber(ARGV[3])  -- unix seconds

  -- Position within current window (0.0 - 1.0)
  local windowStart = now - (now % windowSec)
  local elapsed = now - windowStart
  local weight = 1 - (elapsed / windowSec)

  -- Read both counters
  local prevCount = tonumber(redis.call('GET', prevKey)) or 0
  local currCount = tonumber(redis.call('GET', currKey)) or 0

  -- Weighted effective count
  local effectiveCount = prevCount * weight + currCount

  if effectiveCount >= limit then
    return {0, math.ceil(effectiveCount), limit}  -- rejected
  end

  -- Increment current window counter
  local newCount = redis.call('INCR', currKey)
  if newCount == 1 then
    redis.call('EXPIRE', currKey, windowSec * 2)  -- keep prev window alive
  end
  return {1, math.ceil(effectiveCount + 1), limit}  -- allowed
`;

async function slidingWindowCheck(identifier, limit, windowSec) {
  const now = Math.floor(Date.now() / 1000);
  const windowIndex = Math.floor(now / windowSec);
  const currKey = `sw:${identifier}:${windowIndex}`;
  const prevKey = `sw:${identifier}:${windowIndex - 1}`;

  const [allowed, count, cap] = await redis.eval(
    slidingWindowScript, 2, currKey, prevKey,
    limit, windowSec, now
  );
  return { allowed: allowed === 1, count, limit: cap };
}

// Middleware with informative headers
function slidingWindowMiddleware(limit = 100, windowSec = 60) {
  return async (req, res, next) => {
    const id = req.user?.id || req.ip;
    const { allowed, count, limit: cap } = await slidingWindowCheck(id, limit, windowSec);

    res.set('X-RateLimit-Limit', cap);
    res.set('X-RateLimit-Remaining', Math.max(0, cap - count));
    res.set('X-RateLimit-Reset', Math.ceil(Date.now() / 1000 / windowSec) * windowSec);

    if (!allowed) {
      res.set('Retry-After', windowSec);
      return res.status(429).json({
        error: 'Too Many Requests',
        remaining: 0,
        resetAt: new Date(res.get('X-RateLimit-Reset') * 1000).toISOString(),
      });
    }
    next();
  };
}
